import ChangelogSectionV4 from "./components/changelog-section-v4"

export default function Page() {
  return <ChangelogSectionV4 />
}

import ChangelogDateDivider from "./changelog-date-divider"
import ChangelogEntryRow from "./changelog-entry-row"
import { sectionMeta } from "../lib/changelog-content"
import { changelogGroups } from "../lib/changelog-format"

export default function ChangelogSectionV4() {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-4xl px-4">
        <h2 className="text-3xl font-medium tracking-tight sm:text-4xl">
          {sectionMeta.title}
        </h2>

        <div className="mt-12 sm:mt-16">
          {changelogGroups.map((group) => (
            <div key={group.date}>
              <ChangelogDateDivider label={group.label} />
              <div className="my-4">
                {group.entries.map((entry) => (
                  <ChangelogEntryRow key={entry.id} entry={entry} />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  )
}

import { GeistMono } from "geist/font/mono"

/**
 * Section break between date groups: a small uppercase date tag followed by a
 * rule that runs the rest of the row. Stands in for v3's vertical timeline
 * rail without drawing one — each group just opens with its own horizontal
 * line instead of hanging off a continuous spine.
 */
export default function ChangelogDateDivider({ label }: { label: string }) {
  return (
    <div className="flex items-center gap-4 pt-14 pb-6 first:pt-0">
      <span
        className={`${GeistMono.className} shrink-0 text-xs font-medium tracking-widest text-muted-foreground uppercase`}
      >
        {label}
      </span>
      <span aria-hidden className="h-px flex-1 bg-border" />
    </div>
  )
}

import {
  Avatar,
  AvatarFallback,
  AvatarGroup,
  AvatarImage,
} from "@/components/ui/avatar"

import type { Contributor } from "../lib/changelog-content"
import {
  MAX_VISIBLE_CONTRIBUTORS,
  formatContributorNames,
} from "../lib/changelog-format"

export default function ContributorGroup({
  contributors,
}: {
  contributors: Contributor[]
}) {
  // Never more than three avatars — anyone past that is covered by the names
  // label ("…and 2 others"), so there is no "+N" count bubble.
  const visible = contributors.slice(0, MAX_VISIBLE_CONTRIBUTORS)

  return (
    <div className="flex items-center gap-3">
      <AvatarGroup className="shrink-0">
        {visible.map((person) => (
          <Avatar key={person.id} size="sm">
            <AvatarImage
              src={person.avatarSrc}
              alt={person.name}
              className="object-cover object-center"
            />
            <AvatarFallback>{person.initials}</AvatarFallback>
          </Avatar>
        ))}
      </AvatarGroup>
      <span className="min-w-0 text-sm font-medium text-foreground">
        {formatContributorNames(contributors)}
      </span>
    </div>
  )
}

